نقش سازمانی: مدیر انبار و زنجیرهٔ تأمین (warehouse_manager)

درخواست کاربر:
«شوینده و بهداشتی» که همیشه پرفروش است این ماه 7 روز کمبود داشت در حالی که فروشش ثابت بود. چرا؟ (مدیر انبار و زنجیرهٔ تأمین — پخش مواد غذایی آریا)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "supplier_orders",
      "description": "سفارش‌های خرید: تاریخ ثبت، تاریخ تحویل و تأمین‌کننده",
      "dimensions": [
        "supplier",
        "order"
      ],
      "measures": [
        "lead_time_days"
      ]
    },
    {
      "dataset": "reorder_history",
      "description": "تاریخچهٔ نقطهٔ سفارش و سفارش‌های مجدد",
      "dimensions": [
        "category",
        "date"
      ],
      "measures": [
        "reorder_point",
        "order_qty"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "stockout_days",
      "description": "روزهای کمبود (موجودی صفر برای مشتری)",
      "formula": "تعداد روزهای کمبود در بازه",
      "unit": "روز",
      "dimensions": [
        "category",
        "period"
      ]
    },
    {
      "metric": "supplier_lead_time",
      "description": "زمان تحویل تأمین‌کننده",
      "formula": "میانگین روز از ثبت سفارش تا تحویل",
      "unit": "روز",
      "dimensions": [
        "supplier",
        "period"
      ]
    }
  ],
  "business_context": [
    "شرکت پخش با سه دستهٔ اصلی: پرفروش فصلی، پرفروش ثابت و اقلام مکمل",
    "انبار مرکزی تک‌سایتی؛ تأمین از چند تأمین‌کننده داخلی و یک خارجی"
  ]
}

TOOL_CALL:
{
  "tool": "get_metric",
  "arguments": {
    "metrics": [
      "stockout_days"
    ],
    "period": "curr_month",
    "comparison": "prev_month"
  }
}

TOOL_OBSERVATION:
{
  "stockout_days": {
    "prev_month": 0,
    "curr_month": 7,
    "category": "شوینده و بهداشتی",
    "note": "کمبود فقط همین کالا"
  }
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "supplier_orders",
    "filters": {
      "supplier": "تأمین‌کنندهٔ A",
      "period": [
        "prev_month",
        "curr_month"
      ]
    }
  }
}

TOOL_OBSERVATION:
{
  "lead_time_days": {
    "prev_month": 11,
    "curr_month": 21,
    "note": "تأمین‌کنندهٔ A خط تولید این کالا را تغییر داده و زمان تحویل از 11 به 21 روز رسیده؛ نقطهٔ سفارش هنوز روی 11 روز تنظیم است"
  }
}

نقش سازمانی: مدیر انبار و زنجیرهٔ تأمین (warehouse_manager)

درخواست کاربر:
روزهای نگهداشت موجودی این ماه 24 روز بلندتر شده و پول بیشتری در انبار خوابیده. دقیقاً کجا و چرا؟ (مدیر انبار و زنجیرهٔ تأمین — شرکت پخش لوازم خانگی)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "inventory_levels",
      "description": "موجودی میانگین و مصرف به تفکیک دسته و ماه",
      "dimensions": [
        "category",
        "month"
      ],
      "measures": [
        "avg_inventory_m_toman",
        "usage_m_toman"
      ]
    },
    {
      "dataset": "reorder_history",
      "description": "تاریخچهٔ نقطهٔ سفارش و سفارش‌های مجدد",
      "dimensions": [
        "category",
        "date"
      ],
      "measures": [
        "reorder_point",
        "order_qty"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "days_on_hand",
      "description": "روزهای نگهداشت",
      "formula": "میانگین موجودی / مصرف روزانه",
      "unit": "روز",
      "dimensions": [
        "category",
        "period"
      ]
    },
    {
      "metric": "holding_cost",
      "description": "هزینهٔ نگهداشت موجودی",
      "formula": "ارزش موجودی × نرخ نگهداشت سالانه",
      "unit": "میلیون تومان",
      "dimensions": [
        "period"
      ]
    }
  ],
  "business_context": [
    "شرکت پخش با سه دستهٔ اصلی: پرفروش فصلی، پرفروش ثابت و اقلام مکمل",
    "انبار مرکزی تک‌سایتی؛ تأمین از چند تأمین‌کننده داخلی و یک خارجی",
    "معیار اصلی ارزیابی: نرخ پوشش سفارش بدون رشد نامتناسب موجودی"
  ]
}

TOOL_CALL:
{
  "tool": "get_metric",
  "arguments": {
    "metrics": [
      "days_on_hand"
    ],
    "period": [
      "prev_month",
      "curr_month"
    ],
    "comparison": "month_over_month"
  }
}

TOOL_OBSERVATION:
{
  "days_on_hand": {
    "prev_month": 33,
    "curr_month": 57,
    "change": 24
  }
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "inventory_levels",
    "filters": {
      "period": "curr_month"
    }
  }
}

TOOL_OBSERVATION:
{
  "by_category_days_on_hand": {
    "مواد بسته‌بندی": {
      "prev": 36,
      "curr": 61
    },
    "سایر دسته‌ها": {
      "prev": 31,
      "curr": 30
    }
  },
  "avg_inventory_m_toman": {
    "prev_month": 620,
    "curr_month": 1071
  }
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "reorder_history",
    "filters": {
      "category": "مواد بسته‌بندی",
      "period": "curr_month"
    }
  }
}

TOOL_OBSERVATION:
{
  "bulk_purchase": {
    "note": "خرید عمدهٔ دو برابر مصرف ماهانه به‌خاطر تخفیف 11٪ قیمت تأمین‌کننده",
    "usage_note": "مصرف واقعی در حد برآورد اولیه بود و مازاد خرید جذب نشده است"
  }
}

نقش سازمانی: مدیر انبار و زنجیرهٔ تأمین (warehouse_manager)

درخواست کاربر:
این ماه چرخش موجودی بالاتر رفته ولی روزهای کمبود هم زیاد شده. مدیر فروش می‌گوید موجودی را باید کندتر بچرخانیم. درست است؟ (مدیر انبار و زنجیرهٔ تأمین — زنجیرهٔ دارو و ملزومات)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "inventory_levels",
      "description": "موجودی میانگین و مصرف به تفکیک دسته و ماه",
      "dimensions": [
        "category",
        "month"
      ],
      "measures": [
        "avg_inventory_m_toman",
        "usage_m_toman"
      ]
    },
    {
      "dataset": "backorder_log",
      "description": "سفارش‌های عقب‌افتاده به تفکیک روز",
      "dimensions": [
        "date",
        "category"
      ],
      "measures": [
        "orders"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "inventory_turnover",
      "description": "چرخش موجودی",
      "formula": "مصرف دوره / میانگین موجودی",
      "unit": "بار در دوره",
      "dimensions": [
        "category",
        "period"
      ]
    },
    {
      "metric": "stockout_days",
      "description": "روزهای کمبود (موجودی صفر برای مشتری)",
      "formula": "تعداد روزهای کمبود در بازه",
      "unit": "روز",
      "dimensions": [
        "category",
        "period"
      ]
    }
  ],
  "business_context": [
    "شرکت پخش با سه دستهٔ اصلی: پرفروش فصلی، پرفروش ثابت و اقلام مکمل",
    "انبار مرکزی تک‌سایتی؛ تأمین از چند تأمین‌کننده داخلی و یک خارجی"
  ]
}

TOOL_CALL:
{
  "tool": "compare_periods",
  "arguments": {
    "metric": "inventory_turnover",
    "period_a": "prev_month",
    "period_b": "curr_month"
  }
}

TOOL_OBSERVATION:
{
  "turnover": {
    "prev_month": 2.8,
    "curr_month": 3.6
  },
  "by_category": {
    "نوشیدنی": "چرخش از 2.8 به 4.6 (پرومو + تخلیهٔ پایان فصل)",
    "سایر": "ثابت"
  }
}

TOOL_CALL:
{
  "tool": "get_metric",
  "arguments": {
    "metrics": [
      "stockout_days"
    ],
    "period": "curr_month",
    "comparison": "prev_month"
  }
}

TOOL_OBSERVATION:
{
  "stockout_days": {
    "prev_month": 2,
    "curr_month": 5
  },
  "by_category": {
    "لوازم الکترونیک": "کمبود 3 روز اضافه (پیش‌بینی فروش خطا و تأمین کمتر از نیاز)",
    "سایر": "صفر"
  }
}

